import ast
import os
import sys

DST = "/app/tally/reports"
ORIG = "/tmp/orig/tally/reports.py"


def top_names(tree):
    out = []
    for node in tree.body:
        if isinstance(node, (ast.FunctionDef, ast.ClassDef, ast.AsyncFunctionDef)):
            out.append(node.name)
        elif isinstance(node, ast.Assign):
            for t in node.targets:
                if isinstance(t, ast.Name):
                    out.append(t.id)
        elif isinstance(node, ast.AnnAssign) and isinstance(node.target, ast.Name):
            out.append(node.target.id)
    return out


src = open(ORIG, encoding="utf-8").read()
otree = ast.parse(src)
orig_all = top_names(otree)
public = [n for n in dict.fromkeys(orig_all) if not n.startswith("_")]
doc = ast.get_docstring(otree, clean=False)

# __all__ literal text from original
lines = src.split("\n")
all_text = "\n".join(lines[57:94])
assert all_text.startswith("__all__"), all_text[:20]

homes = {}
defs = {}
for root, _, files in os.walk(DST):
    for f in files:
        if not f.endswith(".py") or "__pycache__" in root:
            continue
        p = os.path.join(root, f)
        rel = os.path.relpath(p, DST)[:-3].replace(os.sep, ".")
        if rel == "__init__":
            continue
        if rel.endswith(".__init__"):
            rel = rel[: -len(".__init__")]
        for n in top_names(ast.parse(open(p, encoding="utf-8").read())):
            defs.setdefault(n, []).append(rel)

missing = [n for n in public if n not in defs]
dups = {n: defs[n] for n in public if len(defs.get(n, [])) > 1}
print("missing:", missing)
print("duplicates:", dups)
by_mod = {}
for n in public:
    if n in defs:
        by_mod.setdefault(defs[n][0], []).append(n)

out = ['"""' + doc + '"""', ""]
for m in sorted(by_mod):
    names = sorted(by_mod[m], key=lambda s: (not s.isupper(), s) if False else s)
    stmt = "from tally.reports." + m + " import " + ", ".join(names)
    if len(stmt) > 118:
        stmt = "from tally.reports." + m + " import (\n" + "".join(f"    {n},\n" for n in names) + ")"
    out.append(stmt)
out.append("")
out.append(all_text)
out.append("")
open(os.path.join(DST, "__init__.py"), "w", encoding="utf-8").write("\n".join(out))
print("public:", len(public))

import ast, builtins, dis, importlib, os, sys, types

sys.path.insert(0, "/app")
DST = "/app/tally/reports"
import tally.reports  # noqa

for root, _, files in os.walk(DST):
    for f in sorted(files):
        if not f.endswith(".py"):
            continue
        p = os.path.join(root, f)
        rel = os.path.relpath(p, "/app")[:-3].replace(os.sep, ".")
        if rel.endswith(".__init__"):
            rel = rel[:-9]
        m = importlib.import_module(rel)
        src = open(p, encoding="utf-8").read()
        code = compile(src, p, "exec")

        def walk(c):
            for ins in dis.get_instructions(c):
                if ins.opname in ("LOAD_GLOBAL", "LOAD_NAME"):
                    yield ins.argval
            for k in c.co_consts:
                if isinstance(k, types.CodeType):
                    yield from walk(k)

        names = set(walk(code))
        undefined = [n for n in names if not hasattr(m, n) and not hasattr(builtins, n)]
        tree = ast.parse(src)
        imported = {}
        for node in ast.walk(tree):
            if isinstance(node, ast.Import):
                for a in node.names:
                    imported[(a.asname or a.name).split(".")[0]] = node.lineno
            elif isinstance(node, ast.ImportFrom):
                for a in node.names:
                    imported[a.asname or a.name] = node.lineno
        used = {n.id for n in ast.walk(tree) if isinstance(n, ast.Name)} | {
            n.value.id for n in ast.walk(tree) if isinstance(n, ast.Attribute) and isinstance(n.value, ast.Name)
        }
        # annotations are strings-in-effect but still ast names, fine
        unused = [n for n in imported if n not in used and n != "annotations" and not rel.endswith("__init__") and rel != "tally.reports"]
        if undefined or unused:
            print(rel, "UNDEFINED:", undefined, "UNUSED:", unused)

