import tally.reports as new

tree = ast.parse(open("/tmp/orig/tally/reports.py", encoding="utf-8").read())
names = []
for node in tree.body:
    if isinstance(node, (ast.FunctionDef, ast.ClassDef)):
        names.append(node.name)
    elif isinstance(node, ast.Assign):
        names += [t.id for t in node.targets if isinstance(t, ast.Name)]
assert new.__all__ == orig.__all__
bad = 0
for n in names:
    o = getattr(orig, n)
    if n.startswith("_"):
        if hasattr(new, n):
            print("private exposed", n); bad += 1
        continue
    if not hasattr(new, n):
        print("missing", n); bad += 1; continue
    v = getattr(new, n)
    if type(o) is not type(v) and not (inspect.isclass(o) and inspect.isclass(v)):
        print("kind", n, type(o), type(v)); bad += 1
    if inspect.isfunction(o):
        if str(inspect.signature(o)) != str(inspect.signature(v)):
            print("sig", n, inspect.signature(o), inspect.signature(v)); bad += 1
    elif inspect.isclass(o):
        for m, f in vars(o).items():
            if callable(f) and not m.startswith("__") or m in ("__init__", "__post_init__"):
                try:
                    if str(inspect.signature(f)) != str(inspect.signature(vars(v)[m])):
                        print("msig", n, m); bad += 1
