                    pass
        if sorted(vars(o)) != sorted(vars(v)):
            print("class members differ", n, set(vars(o)) ^ set(vars(v))); bad += 1
    elif not callable(o):
        if o != v:
            print("value", n); bad += 1
print("bad:", bad, "names:", len(names))
