import ast, os, sys

DST = "/app/tally/reports"
LAYER = {"errors": 0, "tables": 0, "state": 0, "system": 0, "formatting": 1, "model": 1, "loading": 2, "aggregate": 3, "renderers": 4, "cli": 5, "__init__": 6}
mods = {}
for root, dirs, files in os.walk(DST):
    dirs[:] = [d for d in dirs if d != "__pycache__"]
    for f in files:
        if f.endswith(".py"):
            p = os.path.join(root, f)
            rel = os.path.relpath(p, DST)[:-3].replace(os.sep, ".")
            name = "tally.reports" + ("" if rel == "__init__" else "." + rel)
            if rel.endswith(".__init__"):
                name = "tally.reports." + rel[:-9]
            mods[name] = p
    for f in files:
        if f.endswith(".py"):
            n = len(open(os.path.join(root, f), encoding="utf-8").read().split("\n")) - (1 if open(os.path.join(root, f)).read().endswith("\n") else 0)
            if n > 400:
                print("TOO LONG", f, n)


def layer(name):
    parts = name.split(".")
    if len(parts) == 2:
        return 6
    return LAYER[parts[2]]


edges = {m: set() for m in mods}
for m, p in mods.items():
    tree = ast.parse(open(p, encoding="utf-8").read())
    for node in ast.walk(tree):
        targets = []
        if isinstance(node, ast.Import):
            targets = [a.name for a in node.names]
        elif isinstance(node, ast.ImportFrom):
            if node.level:
                print("RELATIVE import in", m)
            base = node.module or ""
            for a in node.names:
                full = base + "." + a.name
                targets.append(full if full in mods else base)
        for t in targets:
            if t.split(".")[0] == "tally" and not t.startswith("tally.reports"):
                print("NOT SELF CONTAINED", m, t)
            if t in mods:
                edges[m].add(t)
                if layer(t) > layer(m):
                    print("LAYER VIOLATION", m, "->", t)
            elif t.startswith("tally"):
                print("unknown target", m, t)
        if isinstance(node, ast.Name) and node.id in ("__import__",):
            print("dynamic import", m)
        if isinstance(node, ast.Import) and any(a.name == "importlib" for a in node.names):
            print("importlib", m)

# cycles
state = {}
def dfs(n, stack):
    state[n] = 1
    for t in edges[n]:
        if state.get(t) == 1:
            print("CYCLE", stack + [n, t])
        elif t not in state:
            dfs(t, stack + [n])
    state[n] = 2
for m in mods:
    if m not in state:
        dfs(m, [])
print("modules", len(mods))

# init content
tree = ast.parse(open(os.path.join(DST, "__init__.py"), encoding="utf-8").read())
for i, node in enumerate(tree.body):
    ok = isinstance(node, (ast.Import, ast.ImportFrom)) or (i == 0 and isinstance(node, ast.Expr) and isinstance(node.value, ast.Constant)) or (isinstance(node, ast.Assign) and node.targets[0].id == "__all__")
    if not ok:
        print("BAD INIT STATEMENT", node)
print(sorted(os.listdir(DST)))
